def create_question(question, options, correct_option):
    if not isinstance(question, str):
        raise TypeError("question must be a string")
    if not isinstance(options, list):
        raise TypeError("options must be a list")
    if not options:
        raise ValueError("options must be non-empty")
    if not all(isinstance(option, str) for option in options):
        raise TypeError("options must contain only strings")
    if not isinstance(correct_option, str):
        raise TypeError("correct_option must be a string")
    if correct_option not in options:
        raise ValueError("correct_option must be one of the options")

    return {
        "question": question,
        "options": list(options),
        "correct_option": correct_option,
    }
